  useEffect(()  =>{
    setLoading(true);
    axios({
        method:"GET",
        url:"https://fakestoreapi.com/products",
        
  
    }).then(res => {
        console.log(res.data);
        setData(res.data);
    }).catch(e=>console.log(e))
    .finally(()=> setLoading(false));


  },[])
  
  return (
    <div className='products-container'>
        
        {}
    </div>
  )
}

export default Products
